using System;
using System.Linq;
using System.Collections.Generic;
using IdleIntelligence.Core;
using UnityEngine;
using UnityEngine.UI;
namespace IdleIntelligence.Runtime
{
 // Uses the existing action-card and item-portrait prefabs; transactions stay in the pure core.
 public sealed class ChallengeUI:MonoBehaviour
 {
  GameRuntime game;int family,stage=1;readonly List<string> selected=new List<string>(),links=new List<string>();Transform controls;Text status;string signature="";bool details,loadout;
  public void Initialize(GameRuntime runtime){game=runtime;ItemPortrait.Sprites=game.WorkshopPrefab.ItemSprites;status=WorkshopUIFactory.Label("ChallengeStatus",transform,"",17,60);AdaptiveTextHeight.Attach(status);controls=WorkshopUIFactory.Vertical("ChallengeControls",transform).transform;Defaults();Build();}
  void Defaults(){selected.Clear();if(ChallengeBalance.Families[family]!="no-items")selected.AddRange(game.State.Workshop.equipped.Where(v=>!string.IsNullOrEmpty(v)));links.Clear();links.AddRange(Balance.Hardware.Skip(1).Take(ChallengeRules.Definition(ChallengeBalance.Families[family],stage).NetworkLimit).Select(h=>h.Id));}
  void Update(){if(game==null)return;var s=game.State;if(ChallengeRules.Active(s)){var r=s.Challenges.Run;status.text=ChallengeBalance.Names[ChallengeRules.Index(r.id)]+" · Stufe "+r.stage+"\nHauptspiel vollständig pausiert · "+Math.Floor((s.SavedAt-r.startedAt)/1000)+" s";string next=r.runId+":"+ChallengeRules.Ready(s);if(signature!=next){signature=next;Build();}foreach(var goal in ChallengeRules.Current(s).Goals){var text=controls.Find("Goal-"+goal.Id)?.GetComponent<Text>();if(text!=null)text.text=Goal(goal.Id)+"  "+N(ChallengeRules.GoalValue(s,goal.Id))+" / "+N(goal.Target);}}else status.text="CHALLENGES\n"+s.Challenges.Progress.stars+" Sterne · "+s.Challenges.Progress.stages.Sum()+" erstmals abgeschlossene Stufen";}
  Text Paragraph(string name,string value,int size=14)
  {var t=WorkshopUIFactory.Label(name,controls,value,size,24);AdaptiveTextHeight.Attach(t);return t;}
  string N(ScientificNumber value)=>NumberFormatting.Format(value,game.State.Settings.numberFormat,game.State.Settings.language);
  string Goal(string id){string name;switch(id){case "passive-credits":name="Passive Credits";break;case "regular-credits":name="Produzierte Credits";break;case "paid-milestones":name="Bezahlte Meilensteine";break;case "early-depth":name="Tiefe früher Klassen";break;case "generated-data":name="Erzeugte Daten";break;case "paid-training":name="Bezahlte Trainings";break;case "paid-research":name="Bezahlte Forschung";break;case "class-purchases":name="Klassenkäufe";break;case "quality":name="Qualität";break;case "efficiency":name="Effizienz";break;case "research":name="Forschungsabschlüsse";break;case "different-areas":name="Unterschiedliche Forschungsbereiche";break;case "local-items":name="Lokal hergestellte Items";break;case "local-rarity":name="Lokaler Seltenheitsrang (0–5)";break;case "crafted-types":name="Unterschiedliche lokale Itemtypen";break;case "research-data-spent":name="Bezahlte Forschungsdaten";break;case "active-links":name="Aktive Nachbarn";break;case "prestiges":name="Prestiges";break;case "minimum-int-per-reset":name="Mindest-INT je Reset";break;case "legacy-int":name="Alter INT-Vertrag";break;default:name=id;break;}return UiLocalizedText.Translate(name,game.State.Settings.language);}

  Button Action(string name,string label,System.Action action,bool enabled=true){var b=WorkshopUIFactory.Button(name,controls,label,action);b.interactable=game.Writable&&enabled;return b;}
  void Build()
  {
   WorkshopUIFactory.Clear(controls);var s=game.State;
   if(ChallengeRules.Active(s))
   {
    var run=s.Challenges.Run;var d=ChallengeRules.Current(s);Paragraph("ChallengeRules",d.Rules);Paragraph("IsolationRule","Hier gesammelte Ressourcen, Käufe und Items bleiben im Challenge-Lauf. Beim Abbruch oder Abschluss wird dein gespeichertes Hauptspiel wiederhergestellt. Nur der reguläre Erstabschluss vergibt Sterne und den dauerhaften Familienbonus.");foreach(var goal in d.Goals)Paragraph("Goal-"+goal.Id,Goal(goal.Id)+"  "+N(ChallengeRules.GoalValue(s,goal.Id))+" / "+N(goal.Target));
    Action("CompleteChallenge","Erfolgreich abschließen und Hauptspiel laden",()=>{if(game.Act(v=>ChallengeRules.Return(v,true,run.runId))){signature="";Build();}},ChallengeRules.Ready(s));Action("AbortChallenge","Challenge abbrechen und Hauptspiel laden",()=>{if(game.Act(v=>ChallengeRules.Return(v,false,run.runId))){signature="";Defaults();Build();}});Action("PlayChallenge","Im Challenge-Lauf weiterspielen",()=>game.HardwareTab.onClick.Invoke());return;
   }
   Action("ChallengeFamily",ChallengeBalance.Names[family]+" · Familie wechseln",()=>{family=(family+1)%ChallengeBalance.Families.Length;stage=Math.Min(69,s.Challenges.Progress.stages[family]+1);Defaults();Build();});
   var chooser=WorkshopUIFactory.Horizontal("ChallengeStagePicker",controls);WorkshopUIFactory.Button("PreviousChallengeStage",chooser.transform,"− Stufe",()=>{stage=Math.Max(1,stage-1);Defaults();Build();});var stageLabel=WorkshopUIFactory.Label("SelectedChallengeStage",chooser.transform,stage+"/69",15,44);var stageSize=stageLabel.GetComponent<LayoutElement>();stageSize.minWidth=stageSize.preferredWidth=58;stageSize.flexibleWidth=0;stageLabel.alignment=TextAnchor.MiddleCenter;WorkshopUIFactory.Button("NextChallengeStage",chooser.transform,"Stufe +",()=>{stage=Math.Min(69,stage+1);Defaults();Build();});Action("NextUnfinishedChallenge","Erste neue Stufe auswählen",()=>{stage=Math.Min(69,s.Challenges.Progress.stages[family]+1);Defaults();Build();});
   string id=ChallengeBalance.Families[family];var quote=ChallengeRules.Definition(id,stage);Paragraph("ChallengeRules",quote.Rules);if(id=="inflation"&&quote.PriceFactor!=ChallengeBalance.ActualInflationFactor)Paragraph("InflationSourceDifference","Bestandsabweichung: Der Katalog nennt ×"+quote.PriceFactor+", die aktuelle Preisfunktion berechnet ×"+ChallengeBalance.ActualInflationFactor+". Die Hardwarepreise folgen der tatsächlichen Preisfunktion.");foreach(var g in quote.Goals)Paragraph("Target-"+g.Id,"Ziel: "+Goal(g.Id)+" · "+N(g.Target));
   bool already=s.Challenges.Progress.stages[family]>=stage;Paragraph("ChallengeRewards",already?"Wiederholung: keine weiteren Sterne und kein zusätzlicher Familienbonus. Eine schnellere Bestzeit zählt.":"Erstabschluss: "+quote.Stars+" Sterne · Familienbonus bis "+(100*ChallengeBalance.RewardCoefficient*Math.Log(1+stage)).ToString("F2",System.Globalization.CultureInfo.GetCultureInfo(game.State.Settings.language))+" %. Freischaltungen richten sich nach der Summe aller erstmals abgeschlossenen Stufen.");
   Action("ChallengeDetails","Regeln und Erhaltung · "+(details?"−":"+"),()=>{details=!details;Build();});if(details)Paragraph("ChallengeRetention","Hauptspiel, laufende Aufträge und Zeitboni werden pausiert und separat gespeichert. Der Challenge-Lauf startet mit 50 Credits, ohne Hauptspielguthaben oder Materialien. Dauerhafte Forschung, aktive Knoten, Axiomwirkungen und ein gewählter Ausrüstungssatz wirken gemäß Originalregeln. Axiome, Modellwechsel und permanente Knotenkäufe sind während des Laufs gesperrt.");
   if(id!="no-items")Action("ChallengeEquipment","Ausrüstung · "+selected.Count+" / "+Workshop.ActiveSlots(s).Count(v=>v)+" · "+(loadout?"−":"+"),()=>{loadout=!loadout;Build();});
   if(id!="no-items"&&loadout)
   {
    Paragraph("ChallengeLoadout","Ausrüstung wählen: "+selected.Count+" / "+Workshop.ActiveSlots(s).Count(v=>v)+" Slots. Die Originalitems bleiben im Hauptspiel; im Lauf sind nur gesperrte Kopien vorhanden.");
    foreach(var item in s.Workshop.inventory){var i=item;var row=Instantiate(game.CardPrefab,controls);row.name="ChallengeLoadout-"+i.id;row.Title.text=(selected.Contains(i.id)?"✓ ":"")+Workshop.Definition(i).Name;row.Detail.text=ItemBalance.Rarities[i.rarity]+" · Lv "+i.level+" · +"+i.forge;row.Icon.color=Color.clear;var icon=Instantiate(game.WorkshopPrefab.PortraitPrefab,row.Icon.transform);var rect=(RectTransform)icon.transform;rect.anchorMin=rect.anchorMax=new Vector2(.5f,.5f);rect.sizeDelta=new Vector2(58,58);rect.anchoredPosition=Vector2.zero;icon.Bind(i);icon.Caption.text="";icon.Button.interactable=false;icon.Button.targetGraphic.raycastTarget=false;row.Button.onClick.AddListener(()=>{if(selected.Contains(i.id))selected.Remove(i.id);else selected.Add(i.id);Build();});}
   }
   else if(id=="no-items")Paragraph("NoItemLoadout","Bare Metal: keine Itemkopien und keine Itemboni.");
   if(id=="fragmented-network")foreach(var h in Balance.Hardware.Skip(1)){string hardware=h.Id;Action("ChallengeLink-"+hardware,(links.Contains(hardware)?"✓ ":"")+h.Name+" · Verbindung vom Vorgänger",()=>{if(links.Contains(hardware))links.Remove(hardware);else links.Add(hardware);Build();});}
   string block=ChallengeRules.EntryBlock(s,id,stage,selected.ToArray(),links.ToArray());Paragraph("ChallengeEntry",block??"Startbereit. Das Hauptspiel wird vor dem Wechsel im atomaren Spielstand erhalten.");Action("StartChallenge","Stufe "+stage+" starten",()=>{string runId="unity:"+id+":"+Guid.NewGuid().ToString("N");if(game.Act(v=>ChallengeRules.Start(v,id,stage,runId,selected.ToArray(),links.ToArray())))game.HardwareTab.onClick.Invoke();},block==null);
  }
 }
}
